    (cnt == 3'd1) ? 9'd65 :
    (cnt == 3'd2) ? 9'd32 :
    (cnt == 3'd3) ? 9'd16 :
    (cnt == 3'd4) ? 9'd16 :
    (cnt == 3'd5) ? 9'd8 :
